const results = [];
const base = DateTime.fromISO($json.timestamp);

for (let i = 1; i <= 7; i++) {
  results.push({
    json: {
      date: base.minus({ days: i }).toFormat('MM/dd/yyyy')
    }
  });
}

return results;

const timeEntries = $input.first().json.data;

const filtered = timeEntries.filter(item => item.client === "Duncan Campbell");

const result = filtered.map(item => {
  const start = DateTime.fromISO(item.start, { zone: 'utc' }).setZone('Asia/Manila');
  const end = DateTime.fromISO(item.end, { zone: 'utc' }).setZone('Asia/Manila');

  return {
    json: {
      date: start.toFormat('cccc, LLLL d, yyyy'),
      startTime: start.toFormat('h:mm a'),
      endTime: end.toFormat('h:mm a'),
      description: item.description
    }
  };
});

return result;

